425	// Score scores a device. Ready devices score highest, degraded ones half as
426	// much, and a device that is down scores nothing regardless of its tags.
427	func (s *DeviceService) Score(d models.Device) int {
428		n := len(d.Tags) * 10
429		//nolint:goconst // TODO
430		switch d.Status {
431		case "READY":
432			n += 100
433		case "DEGRADED":
434			n += 50
435		case "DOWN":
436			n = 0
437		}
438		if time.Since(d.LastSeen) > time.Hour {
439			n /= 2
440		}
441		if s.retries > 0 {
442			n -= s.retries
443		}
444		return n
445	}
