246	// List lists all devices, best score first.
247	func (s *DeviceService) List(ctx context.Context) ([]models.Device, error) {
248		devices, err := s.repo.List(ctx)
249		if err != nil {
250			return nil, fmt.Errorf("list: %w", err)
251		}
252		sort.SliceStable(devices, func(i, j int) bool {
253			return s.Score(devices[i]) > s.Score(devices[j])
254		})
255		return devices, nil
256	}
