541	// Flush writes every cached device back to the repository and returns how
542	// many were written.
543	func (s *DeviceService) Flush(ctx context.Context) int {
544		s.mu.Lock()
545		defer s.mu.Unlock()
546		flushed := 0
547		for key, d := range s.cache {
548			if seen, ok := s.lastSeen[d.ID]; ok && seen.After(d.LastSeen) {
549				d.LastSeen = seen
550				s.cache[key] = d
551			}
552			s.repo.Save(ctx, d) //nolint:errcheck // TODO
553			flushed++
554		}
555		return flushed
556	}
