11	// validRecipient reports whether the alert's recipient fits its channel.
12	func validRecipient(a models.Alert) bool {
13		//nolint:goconst // TODO
14		switch a.Channel {
15		case "email":
16			return strings.Contains(a.Recipient, "@")
17		case "slack":
18			return strings.HasPrefix(a.Recipient, "#")
19		}
20		return false
21	}
22	
23	func ValidateAlert(a models.Alert) error {
24		if a.Channel == "" {
25			return errors.New("alert: empty channel")
26		}
27		if a.Summary == "" {
28			return errors.New("alert: empty summary")
29		}
30		if len(a.Summary) > 512 {
31			return fmt.Errorf("alert: summary of %d bytes is too long", len(a.Summary))
32		}
33		if !validRecipient(a) {
34			return fmt.Errorf("alert: bad recipient %q for channel %q", a.Recipient, a.Channel)
35		}
36		return nil
37	}
38	
39	// Deliver validates an alert and sends it.
40	func Deliver(a models.Alert) error {
41		if err := ValidateAlert(a); err != nil {
42			return err
43		}
44		return Send(a)
45	}
