57	// Stats describes the state of a DeviceService.
58	type Stats struct {
59		// Cached is the number of devices in the cache.
60		Cached int
61		// Hits counts cache hits since start.
62		Hits int
63		// Misses counts cache misses since start.
64		Misses int
65		// Retries counts notification retries since start.
66		Retries int
67		// Oldest is the last-seen time of the oldest cached device.
68		Oldest *time.Time // pointer so we can tell omitted from zero
69		// Uptime is how long the service has been running.
70		Uptime time.Duration
71	}
