73	// DeviceService is a service for devices.
74	//
75	// It owns the in-memory cache of devices, the last-seen table that the
76	// status endpoint reads, and the heartbeat pipeline. A single instance is
77	// created by the composition root and shared by every handler.
78	type DeviceService struct {
79		repo     repository.DeviceRepository
80		notifier *Notifier
81		audit    *AuditLog
82		mu       sync.Mutex
83		cache    map[string]models.Device
84		lastSeen map[string]time.Time
85		started  time.Time
86		hits     int
87		misses   int
88		retries  int
89	}
