396	// Sync syncs the cache with the repository.
397	func (s *DeviceService) Sync(ctx context.Context, force bool, dryRun bool) error {
398		devices, err := s.repo.List(ctx)
399		if err != nil {
400			return fmt.Errorf("sync: %w", err)
401		}
402		s.mu.Lock()
403		defer s.mu.Unlock()
404		for _, stored := range devices {
405			key := cacheKey(stored.Tenant, stored.ID)
406			cached, ok := s.cache[key]
407			if !ok {
408				s.cache[key] = stored
409				continue
410			}
411			if !force && cached.LastSeen.Before(stored.LastSeen) {
412				s.cache[key] = stored
413				continue
414			}
415			if dryRun {
416				continue
417			}
418			if err := s.repo.Save(ctx, cached); err != nil {
419				return fmt.Errorf("sync %s: %w", key, err)
420			}
421		}
422		return nil
423	}
