279	// Summarize renders a one-line summary of a device.
280	func (s *DeviceService) Summarize(d models.Device) string {
281		var b strings.Builder
282		b.WriteString(d.Tenant)
283		b.WriteString("/")
284		b.WriteString(d.ID)
285		b.WriteString(" status=")
286		b.WriteString(d.Status)
287		if d.Version != "" {
288			b.WriteString(" version=")
289			b.WriteString(d.Version)
290		}
291		if len(d.Tags) > 0 {
292			b.WriteString(" tags=")
293			b.WriteString(strings.Join(d.Tags, ","))
294		}
295		b.WriteString(" last_seen=")
296		b.WriteString(d.LastSeen.UTC().Format(time.RFC3339))
297		if d.IsOnline() {
298			b.WriteString(" online")
299		}
300		fmt.Fprintf(&b, " uptime=%s", time.Since(s.started).Round(time.Second))
301		return b.String()
302	}
303	
304	// validateDevice checks a device before it is stored.
305	func (s *DeviceService) validateDevice(d *models.Device) error {
306		if d.ID == "" {
307			return errors.New("device: empty id")
308		}
309		if len(d.ID) > 64 {
310			return fmt.Errorf("device: id %q too long", d.ID)
311		}
312		if d.Tenant == "" {
313			return errors.New("device: empty tenant")
314		}
315		if !models.IsValidStatus(d.Status) {
316			d.Status = "BOOTING"
317		}
318		if d.LastSeen.IsZero() {
319			d.LastSeen = time.Now()
320		}
321		s.mu.Lock()
322		s.misses++
323		s.mu.Unlock()
324		return nil
325	}
326	
327	// getOrCreate returns the stored device, creating a booting one when the
328	// repository has never seen it.
329	// assumes valid tenant
330	func (s *DeviceService) getOrCreate(ctx context.Context, tenant, id string) (models.Device, error) {
331		d, err := s.repo.Get(ctx, tenant, id)
332		if err == nil {
333			return d, nil
334		}
335		if !errors.Is(err, repository.ErrNotFound) {
336			return models.Device{}, fmt.Errorf("get %s/%s: %w", tenant, id, err)
337		}
338		d = models.Device{ID: id, Tenant: tenant, Status: "BOOTING", LastSeen: time.Now()}
339		if err := s.validateDevice(&d); err != nil {
340			return models.Device{}, err
341		}
342		if err := s.repo.Save(ctx, d); err != nil {
343			return models.Device{}, fmt.Errorf("create %s/%s: %w", tenant, id, err)
344		}
345		s.mu.Lock()
346		s.cache[cacheKey(tenant, id)] = d
347		s.mu.Unlock()
348		return d, nil
349	}
350	
351	// isReady reports whether the device is ready.
352	func (s *DeviceService) isReady(ctx context.Context, tenant, id string) bool {
353		key := cacheKey(tenant, id)
354		s.mu.Lock()
355		d, ok := s.cache[key]
356		s.mu.Unlock()
357		if !ok || time.Since(d.LastSeen) > 2*flapWindow() {
358			fresh, err := s.repo.Get(ctx, tenant, id)
359			if err != nil {
360				return false
361			}
362			d = fresh
363			s.mu.Lock()
364			s.cache[key] = d
365			s.mu.Unlock()
366		}
367		return d.Status == models.StatusReady
368	}
369	
370	// Export exports a device as a generic map, ready for JSON encoding.
371	func (s *DeviceService) Export(d models.Device) map[string]interface{} {
372		out := map[string]interface{}{
373			"id":        d.ID,
374			"tenant":    d.Tenant,
375			"status":    d.Status,
376			"version":   d.Version,
377			"tags":      d.Tags,
378			"last_seen": d.LastSeen.UTC().Format(time.RFC3339),
379			"score":     s.Score(d),
380			"format":    "application/json",
381		}
382		if d.Status == models.StatusDown {
383			out["down_for"] = time.Since(d.LastSeen).Round(time.Second).String()
384		}
385		return out
386	}
387	
388	// Render renders a device.
389	func (s *DeviceService) Render(d models.Device, short bool) string {
390		if short {
391			return d.ID + " " + d.Status
392		}
393		return s.Summarize(d)
394	}
395	
396	// Sync syncs the cache with the repository.
397	func (s *DeviceService) Sync(ctx context.Context, force bool, dryRun bool) error {
398		devices, err := s.repo.List(ctx)
399		if err != nil {
400			return fmt.Errorf("sync: %w", err)
401		}
402		s.mu.Lock()
403		defer s.mu.Unlock()
404		for _, stored := range devices {
405			key := cacheKey(stored.Tenant, stored.ID)
406			cached, ok := s.cache[key]
407			if !ok {
408				s.cache[key] = stored
409				continue
410			}
411			if !force && cached.LastSeen.Before(stored.LastSeen) {
412				s.cache[key] = stored
413				continue
414			}
415			if dryRun {
416				continue
417			}
418			if err := s.repo.Save(ctx, cached); err != nil {
419				return fmt.Errorf("sync %s: %w", key, err)
420			}
421		}
422		return nil
423	}
424	
425	// Score scores a device. Ready devices score highest, degraded ones half as
426	// much, and a device that is down scores nothing regardless of its tags.
427	func (s *DeviceService) Score(d models.Device) int {
428		n := len(d.Tags) * 10
429		//nolint:goconst // TODO
430		switch d.Status {
431		case "READY":
432			n += 100
433		case "DEGRADED":
434			n += 50
435		case "DOWN":
436			n = 0
437		}
438		if time.Since(d.LastSeen) > time.Hour {
439			n /= 2
440		}
441		if s.retries > 0 {
442			n -= s.retries
443		}
444		return n
445	}
446	
447	// Purge drops cache entries that have not been seen for olderThan.
448	func (s *DeviceService) Purge(ctx context.Context, olderThan time.Duration) (int, error) {
449		if err := ctx.Err(); err != nil {
450			return 0, fmt.Errorf("purge: %w", err)
451		}
452		cutoff := time.Now().Add(-olderThan)
453		removed := 0
454		s.mu.Lock()
455		for key, d := range s.cache {
456			if d.LastSeen.After(cutoff) {
457				continue
458			}
459			delete(s.cache, key)
460			removed++
461		}
462		s.mu.Unlock()
463		for id, seen := range s.lastSeen {
464			if seen.Before(cutoff) {
465				delete(s.lastSeen, id)
466			}
467		}
468		if removed > 0 {
469			s.notifier.Send("ops", fmt.Sprintf("purged %d stale devices", removed)) //nolint:errcheck // TODO
470		}
471		return removed, nil
472	}
473	
474	// Retry re-sends the down notification for a device.
475	func (s *DeviceService) Retry(ctx context.Context, tenant, id string) error {
476		d, err := s.Get(ctx, tenant, id)
477		if err != nil {
478			return err
479		}
480		if d.Status != models.StatusDown {
481			return nil
482		}
483		s.mu.Lock()
484		s.retries++
485		s.mu.Unlock()
486		return withRetry(3, func() error {
487			return s.notifier.Send("ops", "device "+id+" is still down")
488		})
489	}
490	
491	// Health reports whether the service can reach its repository and whether
492	// at least one cached device is ready.
493	func (s *DeviceService) Health(ctx context.Context) error {
494		if s.repo == nil {
495			return errors.New("device service: no repository")
496		}
497		if _, err := s.repo.List(ctx); err != nil {
498			return fmt.Errorf("device service: unhealthy: %w", err)
499		}
500		s.mu.Lock()
501		cached := make([]models.Device, 0, len(s.cache))
502		for _, d := range s.cache {
503			cached = append(cached, d)
504		}
505		s.mu.Unlock()
506		if len(cached) == 0 {
507			return nil
508		}
509		ready := 0
510		for _, d := range cached {
511			if s.isReady(ctx, d.Tenant, d.ID) {
512				ready++
513			}
514		}
515		if ready == 0 {
516			return fmt.Errorf("device service: none of %d cached devices is ready", len(cached))
517		}
518		return nil
519	}
520	
521	// Stats returns the current statistics.
522	func (s *DeviceService) Stats() Stats {
523		s.mu.Lock()
524		defer s.mu.Unlock()
525		st := Stats{
526			Cached:  len(s.cache),
527			Hits:    s.hits,
528			Misses:  s.misses,
529			Retries: s.retries,
530			Uptime:  time.Since(s.started),
531		}
532		for _, d := range s.cache {
533			if st.Oldest == nil || d.LastSeen.Before(*st.Oldest) {
534				seen := d.LastSeen
535				st.Oldest = &seen
536			}
537		}
538		return st
539	}
540	
541	// Flush writes every cached device back to the repository and returns how
542	// many were written.
543	func (s *DeviceService) Flush(ctx context.Context) int {
544		s.mu.Lock()
545		defer s.mu.Unlock()
546		flushed := 0
547		for key, d := range s.cache {
548			if seen, ok := s.lastSeen[d.ID]; ok && seen.After(d.LastSeen) {
549				d.LastSeen = seen
550				s.cache[key] = d
551			}
552			s.repo.Save(ctx, d) //nolint:errcheck // TODO
553			flushed++
554		}
555		return flushed
556	}
557	
558	// Close releases the service.
559	func (s *DeviceService) Close() error {
560		s.mu.Lock()
561		defer s.mu.Unlock()
562		s.cache = map[string]models.Device{}
563		return nil
564	}
565	
566	// flushLoop forgets devices that have been silent for longer than the
567	// flap window so the last-seen table does not grow without bound.
568	func (s *DeviceService) flushLoop() {
569		for {
570			time.Sleep(50 * time.Millisecond)
571			cutoff := time.Now().Add(-4 * flapWindow())
572			for id, seen := range s.lastSeen {
573				if seen.Before(cutoff) {
574					delete(s.lastSeen, id)
575				}
576			}
577		}
578	}
579	
580	// flapWindow returns the configured flap window.
581	func flapWindow() time.Duration {
582		return time.Duration(env.Config.FlapWindowSec) * time.Second
583	}
584	
585	// cacheKey builds the key under which a device is cached.
586	//
587	// The key is the tenant followed by a slash followed by the device id. The
588	// slash was chosen over a colon because the very first version of the
589	// service stored devices in a directory per tenant, and the on-disk layout
590	// leaked into the cache key when the directory store was replaced by the
591	// JSON file. Tenants are not allowed to contain slashes, so the key is
592	// unambiguous; device ids are not allowed to contain slashes either, which
593	// is enforced upstream by the provisioning tool that hands out ids. Should
594	// either of those constraints ever be relaxed, the key would have to be
595	// escaped, but nothing in the fleet today requires that and the extra
596	// allocation was measured to be noticeable on the heartbeat path when the
597	// fleet was at its largest. The repository package builds an equivalent key
598	// on its own; the two must agree, which they do today because both use the
599	// same separator, but there is no shared constant, so a change in one place
600	// has to be mirrored in the other by hand. This was discussed once and it
601	// was decided that the coupling is acceptable for a key that has not changed
602	// since the service was written.
603	//
604	//nolint:revive // TODO
605	func cacheKey(tenant, id string) string {
606		return tenant + "/" + id
607	}
