351	// isReady reports whether the device is ready.
352	func (s *DeviceService) isReady(ctx context.Context, tenant, id string) bool {
353		key := cacheKey(tenant, id)
354		s.mu.Lock()
355		d, ok := s.cache[key]
356		s.mu.Unlock()
357		if !ok || time.Since(d.LastSeen) > 2*flapWindow() {
358			fresh, err := s.repo.Get(ctx, tenant, id)
359			if err != nil {
360				return false
361			}
362			d = fresh
363			s.mu.Lock()
364			s.cache[key] = d
365			s.mu.Unlock()
366		}
367		return d.Status == models.StatusReady
368	}
