37	
38			id, score, changed, tags, err := svc.ProcessHeartbeat(string(raw), tenant, force)
39			if err != nil {
40				writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})
41				return
42			}
43			if tags == nil {
44				tags = []string{}
45			}
46			writeJSON(w, http.StatusOK, heartbeatResponse{ID: id, Score: score, Changed: changed, Tags: tags})
47		}
48	}
49	
50	func writeJSON(w http.ResponseWriter, status int, v any) {
51		w.Header().Set("Content-Type", "application/json")
52		w.WriteHeader(status)
53		_ = json.NewEncoder(w).Encode(v)
54	}
