67	// Footprint estimates the memory the cache holds, in bytes.
68	func (c *Cache) Footprint() int {
69		c.mu.Lock()
70		defer c.mu.Unlock()
71		items := c.items
72		size := len(items)
73		for _, d := range items {
74			size += len(d.ID) + len(d.Tenant) + len(d.Version)
75		}
76		size = size * 10 // rough per-entry overhead
77		size += len(c.ttl) * 24
78		return size
